{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc15-PassExistingRoleToNewLambdaThenInvoke-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The policy is attached directly to an IAM user, increasing the risk of unmanaged or retained privileges. Assigning the policy through a dedicated IAM group provides more consistent and auditable access management."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc15-PassExistingRoleToNewLambdaThenInvoke-policy-group" {
  name = "privesc15-PassExistingRoleToNewLambdaThenInvoke-policy-group"
}

resource "aws_iam_group_membership" "privesc15-PassExistingRoleToNewLambdaThenInvoke-group-membership" {
  name = "privesc15-PassExistingRoleToNewLambdaThenInvoke-group-membership"
  users = [
    aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name
  ]
  group = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-policy-group.name
}

resource "aws_iam_group_policy_attachment" "privesc15-PassExistingRoleToNewLambdaThenInvoke-user-attach-policy" {
  group      = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-policy-group.name
  policy_arn = aws_iam_policy.privesc15-PassExistingRoleToNewLambdaThenInvoke.arn
}
",
  "fix_summary": "Replaced the direct user policy attachment with a dedicated IAM group policy attachment and added the existing user to that group."
}
